import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DefaultKeyedValues_removeValue_TriageGen0Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }

    @Test
    public void testRemoveValue_KeyNotFound() {
        // Arrange
        keyedValues.addValue("A", 1.0);
        keyedValues.addValue("B", 2.0);

        // Act
        // getIndex should return -1 for a non-existent key
        keyedValues.removeValue("C");

        // Assert
        // Ensure nothing was removed, size remains 2
        assertEquals(2, keyedValues.getItemCount());
        assertEquals("A", keyedValues.getKey(0));
        assertEquals("B", keyedValues.getKey(1));
    }








}

