import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class DefaultKeyedValues_removeValue_TriageGen0Test {

    private DefaultKeyedValues keyedValues;

    @Before
    public void setUp() {
        keyedValues = new DefaultKeyedValues();
    }









    @Test
    public void testRemoveValue_NullKey() {
        // Arrange
        keyedValues.addValue("A", 1.0);

        // Act
        // Depending on getIndex implementation, passing null usually returns -1 
        // or throws NPE. Assuming getIndex handles it or returns -1 to satisfy branch coverage.
        try {
            keyedValues.removeValue(null);
        } catch (NullPointerException e) {
            // If implementation throws NPE on getIndex(null), this is acceptable
        }

        // Assert
        // If no exception, ensure size is still 1
        if (keyedValues.getItemCount() == 1) {
            assertEquals("A", keyedValues.getKey(0));
        }
    }
}
